(()=>{
const pt=document.documentElement.lang==='pt-BR',t=(en,br)=>pt?br:en;
const mny=v=>v===null?'—':new Intl.NumberFormat(pt?'pt-BR':'en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const pct=v=>v===null?'—':new Intl.NumberFormat(pt?'pt-BR':'en-US',{style:'percent',maximumFractionDigits:1}).format(v);
const num=v=>v===null?'—':new Intl.NumberFormat(pt?'pt-BR':'en-US',{maximumFractionDigits:1}).format(v);
let costs={...SalesModel.defaults},view='prospecting';
const root=document.createElement('section');root.id='commercial-dashboard';root.className='commercial-dashboard';
root.innerHTML=`<div class="section-shell"><div class="module-heading"><div><p class="eyebrow">${t('PROSPECTING · SALES · CUSTOMER ECONOMICS','PROSPECÇÃO · VENDAS · ECONOMIA DO CLIENTE')}</p><h2>${t('Follow the numbers.<br>Understand the denominator.','Acompanhe os números.<br>Entenda o denominador.')}</h2><p>${t('One synthetic acquisition cohort and a separate existing-customer cohort. Change cost assumptions and inspect the formulas. All amounts are illustrative USD.','Uma coorte fictícia de aquisição e outra de clientes existentes. Altere as premissas de custo e consulte as fórmulas. Todos os valores são ilustrativos em USD.')}</p></div><span class="module-badge">${t('Q3 2026 · FICTIONAL','3º TRI 2026 · FICTÍCIO')}</span></div><div class="scenario-banner"><strong>${t('Reference period: 1 July–30 September 2026','Período de referência: 1º de julho a 30 de setembro de 2026')}</strong><p>${t('Acquisition: 240 contacts, 24 opportunities and 12 first-time customers. Retention: 20 customers already active at the start, excluding all 12 new customers. This model assumes the acquisition spend is attributable to the same cohort. In real enterprise sales, cost and contract timing often differ.','Aquisição: 240 contatos, 24 oportunidades e 12 novos clientes. Retenção: 20 clientes ativos no início, excluindo os 12 novos clientes. O modelo supõe que os gastos de aquisição sejam atribuíveis à mesma coorte. Em vendas enterprise reais, custos e contratos frequentemente ocorrem em períodos diferentes.')}</p></div><div class="dashboard-tabs" role="tablist" aria-label="${t('Commercial dashboard views','Visões do dashboard comercial')}">${[['prospecting','Prospecting','Prospecção'],['sales','Sales','Vendas'],['economics','Acquisition & margin','Aquisição e margem'],['retention','Retention','Retenção'],['formulas','Data & formulas','Dados e fórmulas']].map(([id,en,br])=>`<button id="dash-tab-${id}" type="button" role="tab" aria-controls="dashboard-panel" aria-selected="${id===view}" data-dash-tab="${id}">${t(en,br)}</button>`).join('')}</div><div id="dashboard-panel" role="tabpanel" aria-labelledby="dash-tab-prospecting" tabindex="0"></div><details class="cost-assumptions"><summary>${t('Edit the cost assumptions','Editar premissas de custo')}</summary><p>${t('Quarterly allocations, in USD. Sales and marketing costs feed acquisition; customer-success and retention allocations feed retention. These are distinct cost buckets, without double-counting. Changes stay in this page session.','Alocações trimestrais em USD. Custos comerciais e de marketing entram na aquisição; customer success e alocações de retenção entram na retenção. São grupos de custos separados, sem dupla contagem. Mudanças ficam apenas nesta sessão da página.')}</p><form id="cost-form"><fieldset><legend>${t('New-customer acquisition','Aquisição de novos clientes')}</legend>${costInput('marketing','Marketing','Marketing')}${costInput('sales','Sales compensation allocation','Alocação de remuneração comercial')}${costInput('tools','Acquisition tools allocation','Alocação de ferramentas de aquisição')}${costInput('agency','Acquisition agency / services','Agência / serviços de aquisição')}</fieldset><fieldset><legend>${t('Existing-customer retention','Retenção de clientes existentes')}</legend>${costInput('success','Customer success allocation','Alocação de customer success')}${costInput('accountManagement','Account management allocation','Alocação de gestão de contas')}${costInput('retentionPrograms','Retention programs','Programas de retenção')}</fieldset></form><button type="button" id="cost-reset" class="secondary">${t('Restore default costs','Restaurar custos originais')}</button><p id="cost-feedback" role="status" aria-live="polite"></p></details><p class="module-note">${t('Currency displays are rounded to the nearest USD; calculations use unrounded values. No live company, CRM or accounting data is connected. All displayed business metrics in this portfolio are synthetic.','Valores exibidos são arredondados ao USD inteiro; os cálculos usam valores sem arredondamento. Nenhum dado real de empresa, CRM ou contabilidade está conectado. Todos os indicadores comerciais apresentados neste portfólio são fictícios.')}</p></div>`;
document.querySelector('#sales-journey').after(root);
function costInput(key,en,br){return`<label for="cost-${key}">${t(en,br)}<input id="cost-${key}" name="${key}" type="number" min="0" max="10000000" step="100" value="${costs[key]}" inputmode="decimal"></label>`;}
const metric=(label,value,formula,note='')=>`<article class="dashboard-metric"><span>${label}</span><strong>${value}</strong><details><summary>${t('Calculation','Cálculo')}</summary><p>${formula}</p>${note?`<p>${note}</p>`:''}</details></article>`;
const box=(title,body)=>`<article class="dashboard-box"><h3>${title}</h3>${body}</article>`;
function render(){const x=SalesModel.calculate(costs),r=x.retention;document.querySelectorAll('[data-dash-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.dashTab===view)));const panel=document.querySelector('#dashboard-panel');panel.setAttribute('aria-labelledby','dash-tab-'+view);
if(view==='prospecting'){panel.innerHTML=`<div class="dashboard-metrics">${metric(t('Contacts reached','Contatos alcançados'),num(x.reached),t('Count distinct contact IDs with at least one outreach activity: 240.','Contagem de IDs distintos com ao menos uma abordagem: 240.'))}${metric(t('Outreach activities','Atividades de abordagem'),num(x.activities),'360 LinkedIn + 240 Email + 120 WhatsApp = 720.',t('One contact can have several activities.','Um contato pode ter várias atividades.'))}${metric(t('Response rate','Taxa de resposta'),pct(x.responseRate),'120 ÷ 240 = 50%.',t('Unique contacts who replied / unique contacts reached.','Contatos únicos que responderam / contatos únicos alcançados.'))}${metric(t('Interest among replies','Interesse entre respostas'),pct(x.interestRate),'72 ÷ 120 = 60%.',t('Interested contacts / contacts who replied.','Contatos interessados / contatos que responderam.'))}${metric(t('Meetings booked','Reuniões agendadas'),num(x.booked),t('60 distinct contacts with a meeting booked in the scenario.','60 contatos distintos com reunião agendada no cenário.'))}${metric(t('Meeting attendance','Realização de reuniões'),pct(x.attendance),'48 ÷ 60 = 80%.',t('Held meetings / booked meetings in the same cohort.','Reuniões realizadas / agendadas da mesma coorte.'))}</div><div class="dashboard-grid">${box(t('Cohort progression','Evolução da coorte'),funnel(x))}${box(t('Channel activity','Atividade por canal'),`<div class="channel-rows">${x.channels.map(c=>`<div><strong>${c.channel==='Email'?t('Email','E-mail'):c.channel}</strong><span>${c.activities} ${t('activities','atividades')} · ${c.reached} ${t('contacts','contatos')}</span></div>`).join('')}</div><p>${t('Channel reach overlaps. Do not add channel contact counts to calculate total unique reach.','Os contatos se sobrepõem entre canais. Não some os contatos de cada canal para calcular o alcance único total.')}</p>`)}</div>`;}
if(view==='sales'){panel.innerHTML=`<div class="dashboard-metrics">${metric(t('Qualified opportunities','Oportunidades qualificadas'),num(x.opportunities),'24 = 12 '+t('won','ganhas')+' + 8 '+t('lost','perdidas')+' + 4 '+t('open','abertas')+'.')}${metric(t('Proposals issued','Propostas emitidas'),num(x.proposals),'18 ÷ 24 = 75%.',t('18 opportunities reached proposal; they include won, lost and still-open opportunities.','18 oportunidades chegaram à proposta, incluindo ganhas, perdidas e ainda abertas.'))}${metric(t('Closed-deal win rate','Taxa de ganho entre encerradas'),pct(x.winRate),'12 ÷ (12 + 8) = 60%.',t('Excludes the four open opportunities.','Exclui as quatro oportunidades abertas.'))}${metric(t('Average sales cycle','Ciclo médio de venda'),num(x.cycleDays)+' '+t('days','dias'),t('480 total calendar days ÷ 12 won opportunities = 40 days. Start: qualified opportunity creation. End: signature.','480 dias corridos acumulados ÷ 12 oportunidades ganhas = 40 dias. Início: criação da oportunidade qualificada. Fim: assinatura.'),t('Won deals only; it does not describe the age of open or lost opportunities.','Considera apenas vendas ganhas; não descreve a idade de oportunidades abertas ou perdidas.'))}${metric(t('Average contract value','Ticket médio de contrato'),mny(x.averageTicket),'USD 480,000 ÷ 12 = USD 40,000.',t('First signed contract per new customer. Not recurring monthly revenue.','Primeiro contrato assinado por novo cliente. Não é receita recorrente mensal.'))}${metric(t('Signed contract value','Valor de contratos assinados'),mny(x.contractValue),t('Sum of the 12 fictional signed contract values = USD 480,000.','Soma dos 12 contratos fictícios assinados = USD 480.000.'),t('Bookings, not recognized revenue or cash received.','Valor contratado, não receita reconhecida ou recebimento.'))}</div><div class="dashboard-grid">${box(t('Open pipeline','Pipeline aberto'),`<p class="big-number">${mny(x.pipelineValue)}</p><p>${t('Only the four open opportunities: USD 24,000 + 48,000 + 36,000 + 18,000. Won and lost deals are excluded.','Somente as quatro oportunidades abertas: USD 24.000 + 48.000 + 36.000 + 18.000. Ganhas e perdidas ficam de fora.')}</p><h4>${t('Weighted illustrative scenario','Cenário ponderado ilustrativo')}</h4><p class="big-number">${mny(x.weightedPipeline)}</p><p>24.000 × 20% + 48.000 × 40% + 36.000 × 60% + 18.000 × 0% = 45.600.</p><p>${t('Subjective example probabilities. Not a validated forecast, expected revenue or a cash projection. No close-date model is applied.','Probabilidades subjetivas de exemplo. Não é forecast validado, receita esperada ou projeção de caixa. Não aplica modelo de data de fechamento.')}</p>`)}${box(t('Keep conversion definitions distinct','Separe as definições de conversão'),`<p><strong>${pct(x.cohortWinRate)}</strong> ${t('of all created opportunities won: 12 / 24. Open opportunities remain in the denominator.','das oportunidades criadas foram ganhas: 12 / 24. As abertas permanecem no denominador.')}</p><p><strong>${pct(x.proposalToWin)}</strong> ${t('of opportunities that reached proposal won: 12 / 18. This cohort measure includes proposals still open at the snapshot.','das oportunidades que chegaram à proposta foram ganhas: 12 / 18. A medida inclui propostas ainda abertas no recorte.')}</p><p><strong>${pct(x.opportunityRate)}</strong> ${t('of held meetings produced qualified opportunities: 24 / 48.','das reuniões realizadas geraram oportunidades qualificadas: 24 / 48.')}</p>`)}</div>`;}
if(view==='economics'){panel.innerHTML=`<div class="dashboard-metrics">${metric(t('Acquisition cost','Custo de aquisição'),mny(x.acquisition),`${mny(x.costs.marketing)} + ${mny(x.costs.sales)} + ${mny(x.costs.tools)} + ${mny(x.costs.agency)} = ${mny(x.acquisition)}.`,t('Marketing + sales allocation + acquisition tools + acquisition services. Excludes delivery and existing-customer retention.','Marketing + alocação comercial + ferramentas + serviços de aquisição. Exclui entrega e retenção de clientes existentes.'))}${metric('CAC',mny(x.cac),`${mny(x.acquisition)} ÷ ${x.newCustomers} = ${mny(x.cac)}.`,t('Acquisition cost / unique first-time customers acquired in the same fictional cohort. Counts customers, not contracts or renewals.','Custo de aquisição / novos clientes únicos da mesma coorte fictícia. Conta clientes, não contratos ou renovações.'))}${metric(t('Cost per booked meeting','Custo por reunião agendada'),mny(x.costBooked),`${mny(x.acquisition)} ÷ ${x.booked}.`)}${metric(t('Cost per held meeting','Custo por reunião realizada'),mny(x.costHeld),`${mny(x.acquisition)} ÷ ${x.held}.`)}${metric(t('Cost per qualified opportunity','Custo por oportunidade qualificada'),mny(x.costOpportunity),`${mny(x.acquisition)} ÷ ${x.opportunities}.`)}${metric(t('Estimated contract gross margin','Margem bruta estimada dos contratos'),pct(x.grossMargin),'(USD 480,000 − USD 288,000) ÷ USD 480,000 = 40%.',t('Assumes direct delivery costs equal 60% of contract value. Budget estimate, not realized accounting profit.','Supõe custos diretos de entrega de 60% do valor contratado. Estimativa de orçamento, não lucro contábil realizado.'))}</div><div class="dashboard-grid">${box(t('Cost scope matters','O escopo do custo importa'),`<p>${t('Marketing cost per reached contact','Custo de marketing por contato alcançado')}: <strong>${mny(x.marketingCostReached)}</strong> = ${mny(x.costs.marketing)} ÷ ${x.reached}.</p><p>${t('This numerator includes only marketing. It is deliberately different from CAC and the fully allocated meeting/opportunity costs. It is not a cost per opt-in or inbound lead.','Esse numerador inclui apenas marketing. É diferente do CAC e dos custos de reunião/oportunidade com alocação completa. Não é custo por lead inbound ou opt-in.')}</p><p>${t('Edit the assumptions below to see how cost allocation changes these measures without changing the funnel.','Edite as premissas abaixo para ver como a alocação altera esses indicadores sem mudar o funil.')}</p>`)}${box(t('What this model does not estimate','O que este modelo não estima'),`<p>${t('No LTV, LTV/CAC or CAC payback is shown. Those require customer-lifetime assumptions and a margin/cash-recognition profile supported by the business model. A project contract is not automatically recurring revenue.','Não há LTV, LTV/CAC ou payback de CAC. Eles exigem premissas de duração do relacionamento e perfil de margem/reconhecimento de receita coerentes com o negócio. Um contrato de projeto não é automaticamente receita recorrente.')}</p><p>${t('Estimated gross margin excludes acquisition expense, retention, overhead, tax and financing. It is not net margin.','A margem bruta estimada exclui aquisição, retenção, despesas gerais, tributos e financiamento. Não é margem líquida.')}</p>`)}</div>`;}
if(view==='retention'){panel.innerHTML=`<div class="scenario-banner"><strong>${t('Separate cohort: 20 existing customers at the start','Coorte separada: 20 clientes existentes no início')}</strong><p>${t('18 remained active; 2 churned. Beginning service revenue for a comparable quarter: USD 200,000. Churn: USD 20,000; contraction: USD 10,000; expansion: USD 30,000. New customers are excluded. This is a service-revenue cohort comparison, not a SaaS MRR/ARR claim.','18 permaneceram ativos; 2 saíram. Receita de serviços inicial para um trimestre comparável: USD 200.000. Churn: USD 20.000; contração: USD 10.000; expansão: USD 30.000. Novos clientes ficam de fora. É uma comparação de receita de serviços por coorte, não uma alegação de MRR/ARR SaaS.')}</p></div><div class="dashboard-metrics">${metric(t('Customer retention','Retenção de clientes'),pct(x.customerRetention),'18 ÷ 20 = 90%.',t('Customers retained / customers active at the beginning.','Clientes retidos / clientes ativos no início.'))}${metric(t('Customer churn','Churn de clientes'),pct(x.customerChurn),'(20 − 18) ÷ 20 = 10%.',t('Lost customers / starting customers. Quarterly, not annualized.','Clientes perdidos / clientes iniciais. Trimestral, sem anualização.'))}${metric(t('Gross revenue retention (GRR)','Retenção bruta de receita (GRR)'),pct(x.grr),'(200.000 − 20.000 − 10.000) ÷ 200.000 = 85%.',t('Excludes expansion and all new-customer revenue.','Exclui expansão e toda receita de novos clientes.'))}${metric(t('Net revenue retention (NRR)','Retenção líquida de receita (NRR)'),pct(x.nrr),'(200.000 − 20.000 − 10.000 + 30.000) ÷ 200.000 = 100%.',t('Includes expansion of the starting cohort only. Stable revenue can mask lost customers.','Inclui somente expansão da coorte inicial. Receita estável pode esconder perda de clientes.'))}${metric(t('Retention cost','Custo de retenção'),mny(x.retentionCost),`${mny(x.costs.success)} + ${mny(x.costs.accountManagement)} + ${mny(x.costs.retentionPrograms)} = ${mny(x.retentionCost)}.`,t('Customer success + account management + retention programs. Separate from acquisition costs.','Customer success + gestão de contas + programas de retenção. Separado da aquisição.'))}${metric(t('Cost per retained customer','Custo por cliente retido'),mny(x.costPerRetained),`${mny(x.retentionCost)} ÷ 18 = ${mny(x.costPerRetained)}.`,t('Period retention cost / retained customers. Not CAC and not cost per starting customer.','Custo de retenção do período / clientes retidos. Não é CAC nem custo por cliente inicial.'))}</div>${box(t('Read the two retention lenses together','Leia as duas perspectivas juntas'),`<p>${t('Logo retention is 90%, while net revenue retention is 100%. Expansion among remaining customers offsets churn and contraction in revenue, but two customer relationships were still lost.','A retenção de clientes é 90%, enquanto a retenção líquida de receita é 100%. A expansão nos clientes remanescentes compensa churn e contração em receita, mas duas relações comerciais foram perdidas.')}</p>`)}`;}
if(view==='formulas'){panel.innerHTML=`<div class="dashboard-grid">${box(t('Synthetic data ledger','Resumo dos dados fictícios'),`<dl class="data-ledger"><dt>${t('Acquisition contacts','Contatos de aquisição')}</dt><dd>240</dd><dt>${t('Outreach activities','Atividades de abordagem')}</dt><dd>720</dd><dt>${t('Replies / interest','Respostas / interesse')}</dt><dd>120 / 72</dd><dt>${t('Meetings booked / held','Reuniões agendadas / realizadas')}</dt><dd>60 / 48</dd><dt>${t('Opportunities / proposals','Oportunidades / propostas')}</dt><dd>24 / 18</dd><dt>${t('Won / lost / open','Ganhas / perdidas / abertas')}</dt><dd>12 / 8 / 4</dd><dt>${t('First-time customers','Novos clientes únicos')}</dt><dd>12</dd><dt>${t('Existing / retained customers','Clientes existentes / retidos')}</dt><dd>20 / 18</dd></dl>`)}${box(t('Measurement boundaries','Limites de interpretação'),`<ul><li>${t('Contacts are unique people; opportunities, customers and outreach activities are different units.','Contatos são pessoas únicas; oportunidades, clientes e atividades são unidades diferentes.')}</li><li>${t('The first-time customers in this example have one won contract each. Renewals never enter the CAC denominator.','Cada novo cliente do exemplo tem um contrato ganho. Renovações não entram no denominador do CAC.')}</li><li>${t('Costs are quarter allocations. Real acquisition attribution may require an earlier spend window or cohort lag.','Custos são alocações trimestrais. A atribuição real pode exigir uma janela de gasto anterior ou defasagem da coorte.')}</li><li>${t('A zero denominator is displayed as a dash, never as zero performance or infinity.','Um denominador zero é exibido como traço, nunca como desempenho zero ou infinito.')}</li><li>${t('The lifecycle explorer and the earlier contact/opportunity labs are independent teaching examples. Their edits do not rewrite this quarterly cohort.','A jornada e os laboratórios anteriores são exemplos independentes. Suas edições não reescrevem esta coorte trimestral.')}</li></ul>`)}</div><div class="ledger-wrap"><table><caption>${t('Fictional opportunity ledger · no client identities','Oportunidades fictícias · sem identidades de clientes')}</caption><thead><tr><th>ID</th><th>${t('Outcome','Resultado')}</th><th>${t('Proposal issued','Proposta emitida')}</th><th>${t('Contract / pipeline value (USD)','Contrato / pipeline (USD)')}</th><th>${t('Cycle to signature','Ciclo até assinatura')}</th></tr></thead><tbody>${SalesModel.opportunities.map(o=>`<tr><td>OP-${String(o.id).padStart(2,'0')}</td><td>${o.state==='won'?t('Won','Ganha'):o.state==='lost'?t('Lost','Perdida'):t('Open','Aberta')}</td><td>${o.proposed?t('Yes','Sim'):t('No','Não')}</td><td>${o.state==='lost'?'—':mny(o.contractValue)}</td><td>${o.cycleDays?o.cycleDays+' '+t('days','dias'):'—'}</td></tr>`).join('')}</tbody></table></div><p>${t('Open values are potential contracts; won values are signed bookings. Lost values are omitted from the ledger totals. Neither is recognized revenue.','Valores abertos são contratos potenciais; valores ganhos são contratos assinados. Valores perdidos são omitidos dos totais. Nenhum representa receita reconhecida.')}</p>`;}
}
function funnel(x){const entries=[[t('Reached','Alcançados'),x.reached],[t('Replied','Responderam'),x.replied],[t('Interested','Interessados'),x.interested],[t('Meetings booked','Reuniões agendadas'),x.booked],[t('Meetings held','Reuniões realizadas'),x.held],[t('Opportunities','Oportunidades'),x.opportunities],[t('Proposals','Propostas'),x.proposals],[t('Signed','Assinados'),x.won]];return `<div class="cohort-funnel">${entries.map(([label,n],i)=>`<div><div><span>${label}</span><strong>${n}</strong></div><div class="cohort-track"><span style="width:${n/x.reached*100}%"></span></div><small>${i?t('Previous-stage conversion','Conversão da etapa anterior')+': '+pct(n/entries[i-1][1]):t('Unique contacts in this cohort','Contatos únicos desta coorte')}</small></div>`).join('')}</div>`;}
root.querySelector('.dashboard-tabs').onclick=e=>{const b=e.target.closest('[data-dash-tab]');if(!b)return;view=b.dataset.dashTab;render();};
root.querySelector('.dashboard-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const bs=[...root.querySelectorAll('[data-dash-tab]')],i=bs.indexOf(document.activeElement),n=e.key==='Home'?0:e.key==='End'?bs.length-1:(i+(e.key==='ArrowRight'?1:bs.length-1))%bs.length;view=bs[n].dataset.dashTab;render();bs[n].focus();});
document.querySelector('#cost-form').onsubmit=e=>e.preventDefault();
document.querySelector('#cost-form').addEventListener('input',e=>{if(!(e.target.name in costs))return;costs[e.target.name]=Math.max(0,Math.min(10000000,Number(e.target.value)||0));render();document.querySelector('#cost-feedback').textContent=t('Scenario recalculated. Funnel and cohort counts are unchanged.','Cenário recalculado. Contagens do funil e das coortes permanecem iguais.');});
document.querySelector('#cost-form').addEventListener('change',e=>{if(e.target.name in costs)e.target.value=costs[e.target.name];});
document.querySelector('#cost-reset').onclick=()=>{costs={...SalesModel.defaults};for(const[k,v]of Object.entries(costs))document.querySelector('#cost-'+k).value=v;render();document.querySelector('#cost-feedback').textContent=t('Default costs restored.','Custos originais restaurados.');};render();
})();
